import os
import csv
from collections import defaultdict


# ============================================================
# Configuration
# ============================================================

CSL_STRUCTURE_ROOT = "/prompts/CSL"
PT_STRUCTURE_ROOT = "/prompts/pT"

# Use the span CSV generated by the selected CTC alignment epoch
CSL_SPAN_CSV = "/CSL_ctc_span_epoch40/CSL-span.csv"

PT_SPAN_CSV = (
    "/root/autodl-tmp/z-csl-data/"
    "pT_ctc_span_epoch40/pT-span.csv"
)

CSL_OUTPUT = "/prompts/CSL/csl_train_annotation.txt"
PT_OUTPUT = "/prompts/pT/pT_train_annotation.txt"


# ============================================================
# Load video structure
# ============================================================

def load_video_structure(structure_root, name):
    """
    Load the change-score description corresponding to a video.
    """
    txt_path = os.path.join(structure_root, f"{name}.txt")

    if not os.path.exists(txt_path):
        return None

    with open(txt_path, "r", encoding="utf-8") as f:
        return f.read().strip()


# ============================================================
# Load gloss sequence from span CSV
# ============================================================

def load_gloss_sequences_from_span_csv(span_csv):
    """
    Read:
        video, gloss, start_frame, end_frame

    and convert each video's alignment into:

        1]GLOSS_A(start-end) 2]GLOSS_B(start-end) ...
    """
    video2segments = defaultdict(list)

    with open(span_csv, "r", encoding="utf-8") as f:
        reader = csv.DictReader(f)

        for row in reader:
            video = row["video"].strip()
            gloss = row["gloss"].strip()
            start_frame = int(row["start_frame"])
            end_frame = int(row["end_frame"])

            video2segments[video].append(
                (
                    start_frame,
                    end_frame,
                    gloss
                )
            )

    video2gloss_sequence = {}

    for video, segments in video2segments.items():

        # Sort segments according to their temporal positions
        segments.sort(key=lambda x: (x[0], x[1]))

        gloss_sequence = []

        for idx, (start_frame, end_frame, gloss) in enumerate(
            segments,
            start=1
        ):
            gloss_sequence.append(
                f"{idx}]{gloss}({start_frame}-{end_frame})"
            )

        video2gloss_sequence[video] = " ".join(gloss_sequence)

    return video2gloss_sequence


# ============================================================
# Build annotation file
# ============================================================

def build_annotation_file(
    span_csv,
    structure_root,
    output_file,
    dataset_name
):
    """
    Combine the following three fields for each video:

        name
        gloss_sequence
        video_structure
    """

    os.makedirs(
        os.path.dirname(output_file),
        exist_ok=True
    )

    video2gloss_sequence = load_gloss_sequences_from_span_csv(
        span_csv
    )

    entries = []
    missing_structure = []

    for name in sorted(video2gloss_sequence.keys()):

        video_structure = load_video_structure(
            structure_root,
            name
        )

        if video_structure is None:
            missing_structure.append(name)
            continue

        entry = {
            "name": name,
            "gloss_sequence": video2gloss_sequence[name],
            "video_structure": video_structure,
        }

        entries.append(entry)

    with open(output_file, "w", encoding="utf-8") as f:

        for entry in entries:

            f.write(
                f"name: {entry['name']}\n"
            )

            f.write(
                f"gloss_sequence: "
                f"{entry['gloss_sequence']}\n"
            )

            f.write(
                "video_structure:\n"
            )

            f.write(
                entry["video_structure"]
            )

            f.write("\n")

            f.write(
                "=" * 80
            )

            f.write("\n")

    print(
        f"[{dataset_name}] "
        f"Saved {len(entries)} entries to {output_file}"
    )

    if missing_structure:

        print(
            f"[{dataset_name}] "
            f"Missing video_structure files: "
            f"{len(missing_structure)}"
        )

        for name in missing_structure[:20]:

            print(
                f"  Missing: "
                f"{os.path.join(structure_root, name + '.txt')}"
            )

        if len(missing_structure) > 20:

            print(
                f"  ... and "
                f"{len(missing_structure) - 20} more"
            )


# ============================================================
# Main
# ============================================================

def main():

    # --------------------------------------------------------
    # CSL
    # --------------------------------------------------------

    print("Building CSL training annotation...")

    build_annotation_file(
        span_csv=CSL_SPAN_CSV,
        structure_root=CSL_STRUCTURE_ROOT,
        output_file=CSL_OUTPUT,
        dataset_name="CSL"
    )

    # --------------------------------------------------------
    # PHOENIX-2014-T
    # --------------------------------------------------------

    print("\nBuilding PHOENIX-2014-T training annotation...")

    build_annotation_file(
        span_csv=PT_SPAN_CSV,
        structure_root=PT_STRUCTURE_ROOT,
        output_file=PT_OUTPUT,
        dataset_name="pT"
    )

    print("\nAll annotation files generated.")


if __name__ == "__main__":
    main()